        axpy_cpu(
            l.out_c,
            0.1f32,
            l.mean,
            1 as ::core::ffi::c_int,
            l.rolling_mean,
            1 as ::core::ffi::c_int,
        );
        scal_cpu(l.out_c, 0.9f32, l.rolling_variance, 1 as ::core::ffi::c_int);
        axpy_cpu(
            l.out_c,
            0.1f32,
            l.variance,
            1 as ::core::ffi::c_int,
            l.rolling_variance,
            1 as ::core::ffi::c_int,
        );
        copy_cpu(
            l.outputs * l.batch,
            l.output,
            1 as ::core::ffi::c_int,
            l.x,
            1 as ::core::ffi::c_int,
        );
        normalize_cpu(
            l.output,
            l.mean,
            l.variance,
            l.batch,
            l.out_c,
            l.out_h * l.out_w,
        );
