        (l.h + 2 as ::core::ffi::c_int * l.pad - l.size) / l.stride + 1 as ::core::ffi::c_int;
    let mut out_w: ::core::ffi::c_int =
        (l.w + 2 as ::core::ffi::c_int * l.pad - l.size) / l.stride + 1 as ::core::ffi::c_int;
    let mut i: ::core::ffi::c_int = 0;
    let mut bx: ::core::ffi::c_int = 0;
    let mut j: ::core::ffi::c_int = 0;
    let mut m: ::core::ffi::c_int = 0;
    let mut k: ::core::ffi::c_int = 0;
    let mut n: ::core::ffi::c_int = 0;
    let mut a: *mut ::core::ffi::c_float = ::core::ptr::null_mut::<::core::ffi::c_float>();
    let mut b: *mut ::core::ffi::c_float = ::core::ptr::null_mut::<::core::ffi::c_float>();
    let mut c: *mut ::core::ffi::c_float = ::core::ptr::null_mut::<::core::ffi::c_float>();
