    let mut n: ::core::ffi::c_int = l.size * l.size * l.c;
    let mut k: ::core::ffi::c_int = ((l.h + 2 as ::core::ffi::c_int * l.pad - l.size) / l.stride
        + 1 as ::core::ffi::c_int)
        * ((l.w + 2 as ::core::ffi::c_int * l.pad - l.size) / l.stride + 1 as ::core::ffi::c_int);
