unsafe extern "C" fn update_local_layer(
    mut l: local_layer,
    mut batch: ::core::ffi::c_int,
    mut learning_rate: ::core::ffi::c_float,
    mut momentum: ::core::ffi::c_float,
    mut decay: ::core::ffi::c_float,
) {
    let mut locations: ::core::ffi::c_int = l.out_w * l.out_h;
    let mut size: ::core::ffi::c_int = l.size * l.size * l.c * l.n * locations;
    axpy_cpu(
        l.outputs,
        learning_rate / batch as ::core::ffi::c_float,
        l.bias_updates,
        1 as ::core::ffi::c_int,
        l.biases,
        1 as ::core::ffi::c_int,
    );
    scal_cpu(l.outputs, momentum, l.bias_updates, 1 as ::core::ffi::c_int);
    axpy_cpu(
        size,
        -decay * batch as ::core::ffi::c_float,
        l.weights,
        1 as ::core::ffi::c_int,
        l.weight_updates,
        1 as ::core::ffi::c_int,
    );
    axpy_cpu(
        size,
        learning_rate / batch as ::core::ffi::c_float,
        l.weight_updates,
        1 as ::core::ffi::c_int,
        l.weights,
        1 as ::core::ffi::c_int,
    );
    scal_cpu(size, momentum, l.weight_updates, 1 as ::core::ffi::c_int);
}
