unsafe extern "C" fn parse_local(
    mut l: *mut local_layer,
    mut options: *mut list,
    mut params: size_params,
    mut pNet: *mut sod_cnn,
) -> ::core::ffi::c_int {
    let mut n: ::core::ffi::c_int = option_find_int(
        options,
        b"filters\0".as_ptr() as *const ::core::ffi::c_char as *mut ::core::ffi::c_char,
        1 as ::core::ffi::c_int,
    );
    let mut size: ::core::ffi::c_int = option_find_int(
        options,
        b"size\0".as_ptr() as *const ::core::ffi::c_char as *mut ::core::ffi::c_char,
        1 as ::core::ffi::c_int,
    );
    let mut stride: ::core::ffi::c_int = option_find_int(
        options,
        b"stride\0".as_ptr() as *const ::core::ffi::c_char as *mut ::core::ffi::c_char,
        1 as ::core::ffi::c_int,
    );
    let mut pad: ::core::ffi::c_int = option_find_int(
        options,
        b"pad\0".as_ptr() as *const ::core::ffi::c_char as *mut ::core::ffi::c_char,
        0 as ::core::ffi::c_int,
    );
    let mut activation_s: *mut ::core::ffi::c_char = option_find_str(
        options,
        b"activation\0".as_ptr() as *const ::core::ffi::c_char as *mut ::core::ffi::c_char,
        b"logistic\0".as_ptr() as *const ::core::ffi::c_char as *mut ::core::ffi::c_char,
    );
    let mut activation: ACTIVATION = get_activation(activation_s);
    let mut batch: ::core::ffi::c_int = 0;
    let mut h: ::core::ffi::c_int = 0;
    let mut w: ::core::ffi::c_int = 0;
    let mut c: ::core::ffi::c_int = 0;
    h = params.h;
    w = params.w;
    c = params.c;
    batch = params.batch;
    if !(h != 0 && w != 0 && c != 0) {
        (*pNet).zErr =
            b"Layer before local layer must output image.\0".as_ptr() as *const ::core::ffi::c_char;
        (*pNet).nErr = (*pNet).nErr.wrapping_add(1);
        return -1 as ::core::ffi::c_int;
    }
    *l = make_local_layer(batch, h, w, c, n, size, stride, pad, activation);
    return SOD_OK;
}
unsafe extern "C" fn forward_activation_layer(mut l: layer, mut state: network_state) {
    copy_cpu(
        l.outputs * l.batch,
        state.input,
        1 as ::core::ffi::c_int,
        l.output,
        1 as ::core::ffi::c_int,
    );
    activate_array(l.output, l.outputs * l.batch, l.activation);
}
unsafe extern "C" fn backward_activation_layer(mut l: layer, mut state: network_state) {
    gradient_array(l.output, l.outputs * l.batch, l.activation, l.delta);
    copy_cpu(
        l.outputs * l.batch,
        l.delta,
        1 as ::core::ffi::c_int,
        state.delta,
        1 as ::core::ffi::c_int,
    );
}
