unsafe extern "C" fn read_tree(mut filename: *mut ::core::ffi::c_char) -> *mut tree {
    let mut t: tree = tree {
        leaf: ::core::ptr::null_mut::<::core::ffi::c_int>(),
        n: 0,
        parent: ::core::ptr::null_mut::<::core::ffi::c_int>(),
        child: ::core::ptr::null_mut::<::core::ffi::c_int>(),
        group: ::core::ptr::null_mut::<::core::ffi::c_int>(),
        name: ::core::ptr::null_mut::<*mut ::core::ffi::c_char>(),
        groups: 0,
        group_size: ::core::ptr::null_mut::<::core::ffi::c_int>(),
        group_offset: ::core::ptr::null_mut::<::core::ffi::c_int>(),
    };
    let mut fp: *mut FILE = fopen(filename, b"r\0".as_ptr() as *const ::core::ffi::c_char);
    let mut line: *mut ::core::ffi::c_char = ::core::ptr::null_mut::<::core::ffi::c_char>();
    let mut last_parent: ::core::ffi::c_int = -1 as ::core::ffi::c_int;
    let mut group_size: ::core::ffi::c_int = 0 as ::core::ffi::c_int;
    let mut groups: ::core::ffi::c_int = 0 as ::core::ffi::c_int;
    let mut n: ::core::ffi::c_int = 0 as ::core::ffi::c_int;
    loop {
        line = fgetl(fp);
        if line.is_null() {
            break;
        }
        let mut id: *mut ::core::ffi::c_char =
            calloc(256 as size_t, ::core::mem::size_of::<::core::ffi::c_char>())
                as *mut ::core::ffi::c_char;
        let mut parent: ::core::ffi::c_int = -1 as ::core::ffi::c_int;
        sscanf(
            line,
            b"%255s %d\0".as_ptr() as *const ::core::ffi::c_char,
            id,
            &raw mut parent,
        );
        t.parent = realloc(
            t.parent as *mut ::core::ffi::c_void,
            ((n + 1 as ::core::ffi::c_int) as size_t)
                .wrapping_mul(::core::mem::size_of::<::core::ffi::c_int>()),
        ) as *mut ::core::ffi::c_int;
        *t.parent.offset(n as isize) = parent;
        t.child = realloc(
            t.child as *mut ::core::ffi::c_void,
            ((n + 1 as ::core::ffi::c_int) as size_t)
                .wrapping_mul(::core::mem::size_of::<::core::ffi::c_int>()),
        ) as *mut ::core::ffi::c_int;
        *t.child.offset(n as isize) = -1 as ::core::ffi::c_int;
        t.name = realloc(
            t.name as *mut ::core::ffi::c_void,
            ((n + 1 as ::core::ffi::c_int) as size_t)
                .wrapping_mul(::core::mem::size_of::<*mut ::core::ffi::c_char>()),
        ) as *mut *mut ::core::ffi::c_char;
        *t.name.offset(n as isize) = id;
        if parent != last_parent {
            groups += 1;
            t.group_offset = realloc(
                t.group_offset as *mut ::core::ffi::c_void,
                (groups as size_t).wrapping_mul(::core::mem::size_of::<::core::ffi::c_int>()),
            ) as *mut ::core::ffi::c_int;
            *t.group_offset
                .offset((groups - 1 as ::core::ffi::c_int) as isize) = n - group_size;
            t.group_size = realloc(
                t.group_size as *mut ::core::ffi::c_void,
                (groups as size_t).wrapping_mul(::core::mem::size_of::<::core::ffi::c_int>()),
            ) as *mut ::core::ffi::c_int;
            *t.group_size
                .offset((groups - 1 as ::core::ffi::c_int) as isize) = group_size;
            group_size = 0 as ::core::ffi::c_int;
            last_parent = parent;
        }
        t.group = realloc(
            t.group as *mut ::core::ffi::c_void,
            ((n + 1 as ::core::ffi::c_int) as size_t)
                .wrapping_mul(::core::mem::size_of::<::core::ffi::c_int>()),
        ) as *mut ::core::ffi::c_int;
        *t.group.offset(n as isize) = groups;
        if parent >= 0 as ::core::ffi::c_int {
            *t.child.offset(parent as isize) = groups;
        }
        n += 1;
        group_size += 1;
    }
    groups += 1;
    t.group_offset = realloc(
        t.group_offset as *mut ::core::ffi::c_void,
        (groups as size_t).wrapping_mul(::core::mem::size_of::<::core::ffi::c_int>()),
    ) as *mut ::core::ffi::c_int;
    *t.group_offset
        .offset((groups - 1 as ::core::ffi::c_int) as isize) = n - group_size;
    t.group_size = realloc(
        t.group_size as *mut ::core::ffi::c_void,
        (groups as size_t).wrapping_mul(::core::mem::size_of::<::core::ffi::c_int>()),
    ) as *mut ::core::ffi::c_int;
    *t.group_size
        .offset((groups - 1 as ::core::ffi::c_int) as isize) = group_size;
    t.n = n;
    t.groups = groups;
    t.leaf = calloc(n as size_t, ::core::mem::size_of::<::core::ffi::c_int>())
        as *mut ::core::ffi::c_int;
    let mut i: ::core::ffi::c_int = 0;
    i = 0 as ::core::ffi::c_int;
    while i < n {
        *t.leaf.offset(i as isize) = 1 as ::core::ffi::c_int;
        i += 1;
    }
    i = 0 as ::core::ffi::c_int;
    while i < n {
        if *t.parent.offset(i as isize) >= 0 as ::core::ffi::c_int {
            *t.leaf.offset(*t.parent.offset(i as isize) as isize) = 0 as ::core::ffi::c_int;
        }
        i += 1;
    }
    fclose(fp);
    let mut tree_ptr: *mut tree = calloc(1 as size_t, ::core::mem::size_of::<tree>()) as *mut tree;
    *tree_ptr = t;
    return tree_ptr;
}
