unsafe extern "C" fn forward_normalization_layer(layer: layer, mut state: network_state) {
    let mut k: ::core::ffi::c_int = 0;
    let mut b: ::core::ffi::c_int = 0;
    let mut w: ::core::ffi::c_int = layer.w;
    let mut h: ::core::ffi::c_int = layer.h;
    let mut c: ::core::ffi::c_int = layer.c;
    scal_cpu(
        w * h * c * layer.batch,
        0 as ::core::ffi::c_int as ::core::ffi::c_float,
        layer.squared,
        1 as ::core::ffi::c_int,
    );
    b = 0 as ::core::ffi::c_int;
    while b < layer.batch {
        let mut squared: *mut ::core::ffi::c_float = layer.squared.offset((w * h * c * b) as isize);
        let mut norms: *mut ::core::ffi::c_float = layer.norms.offset((w * h * c * b) as isize);
        let mut input: *mut ::core::ffi::c_float = state.input.offset((w * h * c * b) as isize);
        pow_cpu(
            w * h * c,
            2 as ::core::ffi::c_int as ::core::ffi::c_float,
            input,
            1 as ::core::ffi::c_int,
            squared,
            1 as ::core::ffi::c_int,
        );
        const_cpu(w * h, layer.kappa, norms, 1 as ::core::ffi::c_int);
        k = 0 as ::core::ffi::c_int;
        while k < layer.size / 2 as ::core::ffi::c_int {
            axpy_cpu(
                w * h,
                layer.alpha,
                squared.offset((w * h * k) as isize),
                1 as ::core::ffi::c_int,
                norms,
                1 as ::core::ffi::c_int,
            );
            k += 1;
        }
        k = 1 as ::core::ffi::c_int;
        while k < layer.c {
            copy_cpu(
                w * h,
                norms.offset((w * h * (k - 1 as ::core::ffi::c_int)) as isize),
                1 as ::core::ffi::c_int,
                norms.offset((w * h * k) as isize),
                1 as ::core::ffi::c_int,
            );
            let mut prev: ::core::ffi::c_int = k
                - (layer.size - 1 as ::core::ffi::c_int) / 2 as ::core::ffi::c_int
                - 1 as ::core::ffi::c_int;
            let mut next: ::core::ffi::c_int = k + layer.size / 2 as ::core::ffi::c_int;
            if prev >= 0 as ::core::ffi::c_int {
                axpy_cpu(
                    w * h,
                    -layer.alpha,
                    squared.offset((w * h * prev) as isize),
                    1 as ::core::ffi::c_int,
                    norms.offset((w * h * k) as isize),
                    1 as ::core::ffi::c_int,
                );
            }
            if next < layer.c {
                axpy_cpu(
                    w * h,
                    layer.alpha,
                    squared.offset((w * h * next) as isize),
                    1 as ::core::ffi::c_int,
                    norms.offset((w * h * k) as isize),
                    1 as ::core::ffi::c_int,
                );
            }
            k += 1;
        }
        b += 1;
    }
    pow_cpu(
        w * h * c * layer.batch,
        -layer.beta,
        layer.norms,
        1 as ::core::ffi::c_int,
        layer.output,
        1 as ::core::ffi::c_int,
    );
    mul_cpu(
        w * h * c * layer.batch,
        state.input,
        1 as ::core::ffi::c_int,
        layer.output,
        1 as ::core::ffi::c_int,
    );
}
unsafe extern "C" fn backward_normalization_layer(layer: layer, mut state: network_state) {
    let mut w: ::core::ffi::c_int = layer.w;
    let mut h: ::core::ffi::c_int = layer.h;
    let mut c: ::core::ffi::c_int = layer.c;
    pow_cpu(
        w * h * c * layer.batch,
        -layer.beta,
        layer.norms,
        1 as ::core::ffi::c_int,
        state.delta,
        1 as ::core::ffi::c_int,
    );
    mul_cpu(
        w * h * c * layer.batch,
        layer.delta,
        1 as ::core::ffi::c_int,
        state.delta,
        1 as ::core::ffi::c_int,
    );
}
