unsafe extern "C" fn forward_route_layer(l: route_layer, mut state: network_state) {
    let mut i: ::core::ffi::c_int = 0;
    let mut j: ::core::ffi::c_int = 0;
    let mut offset: ::core::ffi::c_int = 0 as ::core::ffi::c_int;
    i = 0 as ::core::ffi::c_int;
    while i < l.n {
        let mut index: ::core::ffi::c_int = *l.input_layers.offset(i as isize);
        let mut input: *mut ::core::ffi::c_float =
            (*(*state.net).layers.offset(index as isize)).output;
        let mut input_size: ::core::ffi::c_int = *l.input_sizes.offset(i as isize);
        j = 0 as ::core::ffi::c_int;
        while j < l.batch {
            copy_cpu(
                input_size,
                input.offset((j * input_size) as isize),
                1 as ::core::ffi::c_int,
                l.output
                    .offset(offset as isize)
                    .offset((j * l.outputs) as isize),
                1 as ::core::ffi::c_int,
            );
            j += 1;
        }
        offset += input_size;
        i += 1;
    }
}
