unsafe extern "C" fn parse_route(
    mut lr: *mut route_layer,
    mut options: *mut list,
    mut params: size_params,
    mut net: *mut network,
    mut pNet: *mut sod_cnn,
) -> ::core::ffi::c_int {
    let mut l: *mut ::core::ffi::c_char = option_find(
        options,
        b"layers\0".as_ptr() as *const ::core::ffi::c_char as *mut ::core::ffi::c_char,
    );
    if l.is_null() {
        (*pNet).zErr =
            b"Route Layer must specify input layers\0".as_ptr() as *const ::core::ffi::c_char;
        (*pNet).nErr = (*pNet).nErr.wrapping_add(1);
        return -1 as ::core::ffi::c_int;
    }
    let mut len: ::core::ffi::c_int = strlen(l) as ::core::ffi::c_int;
    let mut n: ::core::ffi::c_int = 1 as ::core::ffi::c_int;
    let mut i: ::core::ffi::c_int = 0;
    i = 0 as ::core::ffi::c_int;
    while i < len {
        if *l.offset(i as isize) as ::core::ffi::c_int == ',' as ::core::ffi::c_int {
            n += 1;
        }
        i += 1;
    }
    let mut layers: *mut ::core::ffi::c_int =
        calloc(n as size_t, ::core::mem::size_of::<::core::ffi::c_int>())
            as *mut ::core::ffi::c_int;
    let mut sizes: *mut ::core::ffi::c_int =
        calloc(n as size_t, ::core::mem::size_of::<::core::ffi::c_int>())
            as *mut ::core::ffi::c_int;
    i = 0 as ::core::ffi::c_int;
    while i < n {
        let mut index: ::core::ffi::c_int = atoi(l);
        l = strchr(l, ',' as ::core::ffi::c_int).offset(1 as ::core::ffi::c_int as isize);
        if index < 0 as ::core::ffi::c_int {
            index = params.index + index;
        }
        *layers.offset(i as isize) = index;
        *sizes.offset(i as isize) = (*(*net).layers.offset(index as isize)).outputs;
        i += 1;
    }
    let mut batch: ::core::ffi::c_int = params.batch;
    let mut layer: route_layer = make_route_layer(batch, n, layers, sizes);
    let mut first: convolutional_layer = *(*net).layers.offset(*layers.offset(0isize) as isize);
    layer.out_w = first.out_w;
    layer.out_h = first.out_h;
    layer.out_c = first.out_c;
    i = 1 as ::core::ffi::c_int;
    while i < n {
        let mut index_0: ::core::ffi::c_int = *layers.offset(i as isize);
        let mut next: convolutional_layer = *(*net).layers.offset(index_0 as isize);
        if next.out_w == first.out_w && next.out_h == first.out_h {
            layer.out_c += next.out_c;
        } else {
            layer.out_c = 0 as ::core::ffi::c_int;
            layer.out_w = layer.out_c;
            layer.out_h = layer.out_w;
        }
        i += 1;
    }
    *lr = layer;
    return SOD_OK;
}
unsafe extern "C" fn forward_shortcut_layer(l: layer, mut state: network_state) {
    copy_cpu(
        l.outputs * l.batch,
        state.input,
        1 as ::core::ffi::c_int,
        l.output,
        1 as ::core::ffi::c_int,
    );
    shortcut_cpu(
        l.batch,
        l.w,
        l.h,
        l.c,
        (*(*state.net).layers.offset(l.index as isize)).output,
        l.out_w,
        l.out_h,
        l.out_c,
        l.output,
    );
    activate_array(l.output, l.outputs * l.batch, l.activation);
}
unsafe extern "C" fn backward_shortcut_layer(l: layer, mut state: network_state) {
    gradient_array(l.output, l.outputs * l.batch, l.activation, l.delta);
    axpy_cpu(
        l.outputs * l.batch,
        1 as ::core::ffi::c_int as ::core::ffi::c_float,
        l.delta,
        1 as ::core::ffi::c_int,
        state.delta,
        1 as ::core::ffi::c_int,
    );
    shortcut_cpu(
        l.batch,
        l.out_w,
        l.out_h,
        l.out_c,
        l.delta,
        l.w,
        l.h,
        l.c,
        (*(*state.net).layers.offset(l.index as isize)).delta,
    );
}
