unsafe extern "C" fn parse_shortcut(
    mut rl: *mut layer,
    mut options: *mut list,
    mut params: size_params,
    mut net: *mut network,
) -> ::core::ffi::c_int {
    let mut l: *mut ::core::ffi::c_char = option_find(
        options,
        b"from\0".as_ptr() as *const ::core::ffi::c_char as *mut ::core::ffi::c_char,
    );
    let mut index: ::core::ffi::c_int = atoi(l);
    if index < 0 as ::core::ffi::c_int {
        index = params.index + index;
    }
    let mut batch: ::core::ffi::c_int = params.batch;
    let mut from: layer = *(*net).layers.offset(index as isize);
    *rl = make_shortcut_layer(
        batch, index, params.w, params.h, params.c, from.out_w, from.out_h, from.out_c,
    );
    (*rl).activation = get_activation(option_find_str(
        options,
        b"activation\0".as_ptr() as *const ::core::ffi::c_char as *mut ::core::ffi::c_char,
        b"linear\0".as_ptr() as *const ::core::ffi::c_char as *mut ::core::ffi::c_char,
    ));
    return SOD_OK;
}
unsafe extern "C" fn forward_dropout_layer(mut l: dropout_layer, mut state: network_state) {
    let mut i: ::core::ffi::c_int = 0;
    if state.train == 0 {
        return;
    }
    i = 0 as ::core::ffi::c_int;
    while i < l.batch * l.inputs {
        let mut r: ::core::ffi::c_float = rand_uniform(
            0 as ::core::ffi::c_int as ::core::ffi::c_float,
            1 as ::core::ffi::c_int as ::core::ffi::c_float,
        );
        *l.rand.offset(i as isize) = r;
        if r < l.probability {
            *state.input.offset(i as isize) = 0 as ::core::ffi::c_int as ::core::ffi::c_float;
        } else {
            *state.input.offset(i as isize) *= l.scale;
        }
        i += 1;
    }
}
unsafe extern "C" fn backward_dropout_layer(mut l: dropout_layer, mut state: network_state) {
    let mut i: ::core::ffi::c_int = 0;
    if state.delta.is_null() {
        return;
    }
    i = 0 as ::core::ffi::c_int;
    while i < l.batch * l.inputs {
        let mut r: ::core::ffi::c_float = *l.rand.offset(i as isize);
        if r < l.probability {
            *state.delta.offset(i as isize) = 0 as ::core::ffi::c_int as ::core::ffi::c_float;
        } else {
            *state.delta.offset(i as isize) *= l.scale;
        }
        i += 1;
    }
}
